#include <iostream>
#include <string>

class GradeBook {
public:
    // Constructor delegating validation to setCourseName
    explicit GradeBook(std::string name) {
        setCourseName(name);
    }

    // Validates that courseName does not exceed 25 characters
    void setCourseName(std::string name) {
        if (name.size() <= 25) {
            courseName = name;
        } else {
            // Truncate to first 25 characters
            courseName = name.substr(0, 25);
            std::cout << "Name \"" << name << "\" exceeds maximum length (25).\n"
                         "Limiting courseName to first 25 characters.\n";
        }
    }

    std::string getCourseName() const {
        return courseName;
    }

    void displayMessage() const {
        std::cout << "Welcome to the grade book for\n" << getCourseName() << "!\n";
    }

private:
    std::string courseName;
};

int main() {
    // Create gradeBook1 with a course name exceeding 25 chars
    GradeBook gradeBook1("CS101 Introduction to Programming in C++");
    // Create gradeBook2 with a valid 25-char course name
    GradeBook gradeBook2("CS102 C++ Data Structures");

    std::cout << "gradeBook1's initial course name is: " << gradeBook1.getCourseName()
              << "\ngradeBook2's initial course name is: " << gradeBook2.getCourseName() << "\n\n";

    // Modify gradeBook1 with a valid name
    gradeBook1.setCourseName("CS101 C++ Programming");

    std::cout << "gradeBook1's course name is: " << gradeBook1.getCourseName()
              << "\ngradeBook2's course name is: " << gradeBook2.getCourseName() << "\n";

    return 0;
}
